17	/**
18	 * Custom rule that combines all parameter sets that can be used
19	 * to resolve a specific country.
20	 *
21	 * @package Countries
22	 * @subpackage API
23	 *
24	 * @method AppCountryParamSetInterface|NULL getValidSet()
25	 * @method AppCountryParamSetInterface requireValidSet()
26	 */
27	class AppCountryParamRule extends OrRule
28	{
29	    public function __construct(AppCountryAPIInterface $method)
30	    {
31	        parent::__construct('Selecting the country');
32	
33	        $this
34	            ->addSet(new CountryIDSet($method))
35	            ->addSet(new CountryISOSet($method));
36	    }
37	
38	    /**
39	     * @param AppCountryParamSetInterface|ParamSetInterface $set Only {@see AppCountryParamSetInterface} instances are allowed.
40	     * @return $this
41	     */
42	    public function addSet(AppCountryParamSetInterface|ParamSetInterface $set): self
43	    {
44	        if($set instanceof AppCountryParamSetInterface) {
45	            return parent::addSet($set);
46	        }
47	
48	        throw new CountryAPIException(
49	            'Not a country API parameter set.',
50	            sprintf(
51	                'The param set is of type %s, but must implement %s.',
52	                get_class($set),
53	                AppCountryParamSetInterface::class
54	            ),
55	            CountryAPIException::INVALID_PARAM_SET
56	        );
57	    }
58	
59	    public function getCountry() : ?Application_Countries_Country
60	    {
61	        return $this->getValidSet()?->getCountry();
62	    }
63	}

