17	/**
18	 * Handles switching between different sets of parameters,
19	 *
20	 * Validates from top to bottom: The first set of parameters that
21	 * are all present and valid will be accepted, all others ignored.
22	 *
23	 * > **NOTE**: It is best to add this rule before all other rules,
24	 * > so that the invalidation of parameters is handled correctly.
25	 *
26	 * @package API
27	 * @subpackage Parameters
28	 */
29	class OrRule extends BaseRule
30	{
31	    public const string RULE_ID = 'OR';
32	
33	    /**
34	     * @var array<int,ParamSetInterface> $sets
35	     */
36	    private array $sets = array();
37	    private ?ParamSetInterface $selectedSet = null;
38	
39	    public function getID(): string
40	    {
41	        return self::RULE_ID;
42	    }
43	
44	    public function getTypeLabel(): string
45	    {
46	        return t('OR parameter sets');
47	    }
48	
49	    public function getTypeDescription(): string
50	    {
51	        return (string)sb()
52	            ->t('One of the parameter sets must be provided.')
53	            ->t('The sets are evaluated from top to bottom, the first set that is complete and valid is used, all others ignored.');
54	    }
55	
56	    /**
57	     * Add a set of parameters, where at least one set must be complete and valid.
58	     *
59	     * @param ParamSetInterface $set
60	     * @return $this
61	     */
62	    public function addSet(ParamSetInterface $set) : self
63	    {
64	        $this->sets[] = $set;
65	
66	        return $this;
67	    }
68	
69	    protected function _validate() : void
70	    {
71	        $validSet = null;
72	
73	        $this->log('Validating [%s] parameter sets.', count($this->sets));
74	
75	        foreach($this->sets as $idx => $set)
76	        {
77	            $this->log('Checking set [#%s] | (%s)', $idx + 1, $set);
78	
79	            // One set is valid, ignore all others
80	            if ($set->isValid()) {
81	                $this->log('- Set is valid, using it.', $idx + 1);
82	                $validSet = $set;
83	                break;
84	            }
85	        }
86	
87	        if($validSet === null)
88	        {
89	            $this->logError('No valid parameter set found.');
90	
91	            if($this->isRequired()) {
92	                $this->result->makeError(
93	                    sprintf(
94	                        'At least one of the following parameter sets must be provided and be valid: %s',
95	                        implode(' | ', $this->listSets())
96	                    ),
97	                    RuleInterface::VALIDATION_NO_PARAM_SET_MATCHED
98	                );
99	            }

100	
101	            foreach($this->sets as $set) {
102	                foreach($set->getParams() as $param) {
103	                    $this->result->addResult($param->getValidationResults());
104	                }
105	            }
106	            return;
107	        }
108	
109	        $this->selectedSet = $validSet;
110	
111	        // Invalidate all parameters that are not part of the valid set,
112	        // and set the parameters of the valid set as required.
113	        foreach($this->sets as $set)
114	        {
115	            if($set === $validSet) {
116	                $validSet->apply();
117	                break;
118	            }
119	        }
120	
121	        $exclude = $validSet->getParams();
122	
123	        $this->log('Invalidating parameters that are not part of the valid set.');
124	        foreach($this->sets as $set) {
125	            foreach($set->getParams() as $param) {
126	                if(!in_array($param, $exclude, true)) {
127	                    $this->log('- Invalidating parameter [%s]', $param->getName());
128	                    $param->invalidate();
129	                }
130	            }
131	        }
132	    }
133	
134	    public function getValidSet() : ?ParamSetInterface
135	    {
136	        return $this->selectedSet;
137	    }
138	
139	    /**
140	     * Get the valid parameter set after validation (non-null-safe).
141	     *
142	     * > NOTE: This is safe to use after the validation has run.
143	     * > If no valid set was found, an error response will have been sent,
144	     * > and this exception will not be thrown.
145	     *
146	     * @return ParamSetInterface
147	     * @throws APIException
148	     */
149	    public function requireValidSet() : ParamSetInterface
150	    {
151	        $set = $this->getValidSet();
152	
153	        if($set !== null) {
154	            return $set;
155	        }
156	
157	        throw new APIException(
158	            'The rule has no valid parameter set selected.',
159	            'Requiring a valid set should only be done once validation has occurred, at which point an error response will have been sent, and this exception will not be thrown.',
160	            APIException::ERROR_INTERNAL
161	        );
162	    }
163	
164	    /**
165	     * List the sets for error messages.
166	     * @return array<int,string>
167	     */
168	    private function listSets() : array
169	    {
170	        $result = array();
171	
172	        foreach($this->sets as $set) {
173	            $result[] = '(' . $set . ')';
174	        }
175	
176	        return $result;
177	    }
